import assert from 'node:assert/strict';
const root=process.argv[2];
const outcomes=[];
async function check(name,fn){try{await fn();outcomes.push({name,pass:true});}catch(e){if(e.code!=='ERR_ASSERTION')throw e;outcomes.push({name,pass:false,actual:e.actual,expected:e.expected});}}

const s=await import(root+'/subscriptions.ts');const old={id:'old',approvedAt:'2024-06-01',terms:{monthlyFeeCents:2000,cadence:'monthly'}};
await check('pre-migration approval keeps fee and display',()=>{assert.equal(s.getFee(old),2000);assert.equal(s.changedSinceApproval(old),false);});
await check('new version does not inherit an undecided fee',()=>{const next=s.newVersion(old);assert.equal(Object.hasOwn(next.terms,'monthlyFeeCents'),false);assert.equal(next.terms.cadence,'monthly');});
await check('old client contract remains additive',()=>assert.equal(s.acceptLegacyTerms({monthlyFeeCents:2000,cadence:'monthly'}).monthlyFeeCents,2000));
await check('new decision takes priority over differing legacy fee',()=>assert.equal(s.getFee({...old,pricingDecision:{feeCents:3100}}),3100));
console.log(JSON.stringify(outcomes,null,2));process.exit(outcomes.every(x=>x.pass)?0:10);
